service.method:

SELECT
	  CONTENTS
	, LANGUAGE
FROM
	SLANG
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
AND LANGUAGE   = $S{LANGUAGE}
AND SCREEN_ID  = ${screen_id}
AND CODE       = ${code}


UPDATE
	SLANG
SET
	  CONTENTS       = ${CONTENTS}
	, CHANGE_USER_ID = ${session.ID}
	, CHANGE_DATE    = ${current.date}
	, CHANGE_TIME    = ${current.time}
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
AND LANGUAGE   = ${LANGUAGE}
AND SCREEN_ID  = ${screen_id}
AND CODE       = ${code}


INSERT INTO SLANG
(
	  HOUSE_CODE
	, SCREEN_ID
	, LANGUAGE
	, CODE
	, CONTENTS
	, ADD_USER_ID
	, ADD_DATE
	, ADD_TIME
	, CHANGE_USER_ID
	, CHANGE_DATE
	, CHANGE_TIME
	, DEL_FLAG
) 
VALUES
(
	  ${session.HOUSE_CODE}
	, ${screen_id}
	, ${LANGUAGE}
	, ${code}
	, ${CONTENTS}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, 'N'
)


DELETE FROM
	SLANG
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
AND SCREEN_ID  = ${screen_id}



AND CODE       = ${code}


SELECT DISTINCT
	   LANG.CONTENTS
  FROM SLANG LANG
  JOIN SMUPD MUPD 
    ON LANG.HOUSE_CODE = MUPD.HOUSE_CODE
   AND LANG.CODE	   = MUPD.MENU_ID
   AND LANG.SCREEN_ID  = 'MENU_'||MUPD.MENU_PROFILE_CODE
   AND LANG.LANGUAGE   = ${LANGUAGE}
 WHERE LANG.HOUSE_CODE = ${session.HOUSE_CODE}
   AND MUPD.SCREEN_ID  = ${code}


DELETE FROM
	SMUPD
WHERE
	HOUSE_CODE        = ${session.HOUSE_CODE}
AND COMPANY_CODE      = ${company_code}
AND MENU_PROFILE_CODE = ${menu_profile_code}
AND MENU_ID           = ${menu_id}


		INSERT INTO SMUID
		(
			  HOUSE_CODE
			, SCREEN_ID
			, URL
            , MOBILE_URL
			, ADD_DATE
			, ADD_TIME
			, ADD_USER_ID
			, CHANGE_DATE
			, CHANGE_TIME
			, CHANGE_USER_ID
			, DEL_FLAG
			, MENU_IMG
			, SUMMARY_FLAG
		)
		VALUES
		(
			  ${session.house_code}
			, ${screen_id}
			, ${url}
            , ${mobile_url}
			, ${current.date}
			, ${current.time}
			, ${session.ID}
			, ${current.date}
			, ${current.time}
			, ${session.ID}
			, ${del_flag}
			, ${menu_img}
			, ${summary_flag}
		)


		UPDATE
			SMUID
		SET
			  URL			 = ${url}
            , MOBILE_URL     = ${mobile_url}
			, CHANGE_DATE    = ${current.date}
			, CHANGE_TIME    = ${current.time}
			, CHANGE_USER_ID = ${session.ID}  
			, DEL_FLAG       = ${del_flag}    
			, MENU_IMG       = ${menu_img}    
			, SUMMARY_FLAG   = ${summary_flag}
		WHERE
			HOUSE_CODE     = ${session.house_code}
		AND SCREEN_ID      = ${screen_id}


INSERT INTO SMUPD 
(
	  HOUSE_CODE
	, COMPANY_CODE
	, MENU_PROFILE_CODE
	, MENU_ID
	, SCREEN_ID
	, PARENT_MENU_ID
	, ITEM_SEQ
	, ADD_DATE
	, ADD_TIME
	, ADD_USER_ID
	, CHANGE_DATE
	, CHANGE_TIME
	, CHANGE_USER_ID
	, DEL_FLAG
	, ETC_FLAG
	, HIDDEN_FLAG
	, ICON_TYPE
	, MENU_IMG
	, MODULE
)
VALUES
(
	  ${session.house_code}
	, ${company_code}
	, ${menu_profile_code}
	, ${menu_id}
	, ${screen_id}
	, ${parent_menu_id}
	, ${item_seq}
	, ${current.date}
	, ${current.time}
	, ${session.id}
	, ${current.date}
	, ${current.time}
	, ${session.id}
	, ${del_flag}
	, ${etc_flag}
	, ${hidden_flag}
	, ${icon_type}
	, ${menu_img}
	, ${module}
)


UPDATE
	SMUPD
SET
	  CHANGE_DATE    = ${current.date}
	, CHANGE_TIME    = ${current.time}
	, CHANGE_USER_ID = ${session.ID}
	, SCREEN_ID      = ${screen_id}
	, PARENT_MENU_ID = ${parent_menu_id}
	, ITEM_SEQ       = ${item_seq}
	, DEL_FLAG       = ${del_flag}    
	, ETC_FLAG		 = ${etc_flag}
	, HIDDEN_FLAG    = ${hidden_flag}
	, ICON_TYPE      = ${icon_type}
	, MENU_IMG		 = ${menu_img}
	, MODULE         = ${module}
WHERE
	HOUSE_CODE        = ${session.house_code}
AND MENU_PROFILE_CODE = ${menu_profile_code}
AND MENU_ID           = ${menu_id}


UPDATE
	SMUPD
SET
	  ITEM_SEQ       = ${ITEM_SEQ}
	, PARENT_MENU_ID = ${parent_menu_id}
WHERE
	HOUSE_CODE   = ${session.HOUSE_CODE} 
AND COMPANY_CODE = ${COMPANY_CODE}
AND MENU_PROFILE_CODE = ${menu_profile_code}
AND MENU_ID      = ${MENU_ID}


        INSERT INTO #DB_OWNER#SLANG_HISTORY
		(
			  HISTORY_KEY
			, ACTION_MODE
			, HOUSE_CODE
			, SCREEN_ID
			, LANGUAGE
			, CODE
			, CONTENTS
			, ADD_USER_ID
			, ADD_DATE
			, ADD_TIME
		)
		VALUES
		(
			  ${HISTORY_KEY}
			, ${ACTION_MODE}
			, ${session.HOUSE_CODE}
			, ${screen_id}
			, ${LANGUAGE}
			, ${code}
			, ${CONTENTS}
			, ${session.ID}
			, ${current.DATE}
			, ${current.TIME}
		 )


        INSERT INTO SMUPD_HISTORY
          (
			  HISTORY_KEY
			, ACTION_MODE
			, HOUSE_CODE
			, COMPANY_CODE
			, MENU_PROFILE_CODE
			, MENU_ID
			, SCREEN_ID
			, PARENT_MENU_ID
			, MENU_SEQ
			, ITEM_SEQ
			, ADD_DATE
			, ADD_TIME
			, ADD_USER_ID
			, DEL_FLAG
			, ETC_FLAG
			, HIDDEN_FLAG
			, ICON_TYPE
			, MENU_IMG
			, MODULE
		)
		VALUES
		(
			  ${HISTORY_KEY}
			, ${ACTION_MODE}
			, ${session.HOUSE_CODE}
			, ${company_code}
			, ${menu_profile_code}
			, ${menu_id}
			, ${screen_id}
			, ${parent_menu_id}
			, ${menu_seq}
			, ${item_seq}
			, ${current.DATE}
			, ${current.TIME}
			, ${session.ID}
			, ${del_flag}
			, ${etc_flag}
			, ${hidden_flag}
			, ${icon_type}
			, ${menu_img}
			, ${module}
		)


        INSERT INTO SMUID_HISTORY
		(
			  HISTORY_KEY
			, ACTION_MODE
			, HOUSE_CODE
			, SCREEN_ID
			, PARENT_ID
			, URL
            , MOBILE_URL
			, AUTH_URL
			, ADD_DATE
			, ADD_TIME
			, ADD_USER_ID
			, DEL_FLAG
			, MENU_IMG
			, SUMMARY_FLAG
			, ATTACH_NO
			, HIDDEN_FLAG
		)
		VALUES
		(
			  ${HISTORY_KEY}
			, ${ACTION_MODE}
			, ${session.HOUSE_CODE}
			, ${screen_id}
			, ${parent_id}
			, ${url}
            , ${mobile_url}
			, ${auth_url}
			, ${current.DATE}
			, ${current.TIME}
			, ${session.ID}
			, ${del_flag}
			, ${menu_img}
			, ${summary_flag}
			, ${attach_no}
			, ${hidden_flag}
		)
